//! Fixed-point number formatting for the generated byte streams.
//!
//! A fixture generator has to outrun the reader it feeds, or every measurement
//! taken through it reports the generator rather than the code under test.
//! `std::fmt`'s float path costs roughly a hundred nanoseconds per value, and a
//! coordinate row carries four of them, which caps a `write!`-based generator at
//! about a hundred megabytes a second — below the throughput the mmCIF reader
//! already targets.
//!
//! Coordinates and temperature factors are fixed-point quantities, not general
//! floats: three and two decimal places respectively. Scaling to an integer and
//! placing the point directly turns each one into integer arithmetic, which is
//! what closes the gap.
//!
//! One difference from `std::fmt` is deliberate and bounded. A decimal midpoint
//! such as `100.005` is not exactly representable in binary, and the scaling
//! multiplication rounds it to exactly `10000.5`, destroying the information
//! about which side of the midpoint the original value sat on. The standard
//! formatter converts the exact binary value and therefore knows. So at an exact
//! scaled midpoint the two can differ by one unit in the last place emitted.
//!
//! Reproducing that would mean reimplementing exact decimal conversion, which is
//! not a reasonable thing to carry in a fixture generator: a coordinate that
//! differs by a thousandth of an ångström changes no measurement, and both
//! renderings are valid mmCIF. The tests assert exact agreement everywhere else
//! and bound the disagreement to one unit at a midpoint.

use crate::numeric::f64_to_u64;

/// Digits in the largest `u64`, which bounds the integer buffer.
const DIGIT_CAPACITY: usize = 20;

/// Largest scaled magnitude a `f64` represents exactly as an integer.
const MAXIMUM_SCALED: f64 = 9_007_199_254_740_992.0;

/// Appends a decimal integer.
pub(super) fn push_u64(buffer: &mut Vec<u8>, value: u64) {
    let mut digits = [b'0'; DIGIT_CAPACITY];
    let mut cursor = DIGIT_CAPACITY;
    let mut remaining = value;

    loop {
        cursor -= 1;
        if let Some(slot) = digits.get_mut(cursor) {
            *slot = digit_byte(remaining % 10);
        }
        remaining /= 10;
        if remaining == 0 || cursor == 0 {
            break;
        }
    }

    if let Some(written) = digits.get(cursor..) {
        buffer.extend_from_slice(written);
    }
}

/// Appends a signed decimal integer.
pub(super) fn push_i32(buffer: &mut Vec<u8>, value: i32) {
    if value.is_negative() {
        buffer.push(b'-');
    }
    push_u64(buffer, u64::from(value.unsigned_abs()));
}

/// Appends `value` with exactly `decimals` places after the point.
///
/// A value that is not finite, or too large for the exact-integer range, is
/// written as the mmCIF unknown sentinel: a coordinate that is not a number is
/// not a coordinate, and saying so is better than emitting a rounded fiction.
pub(super) fn push_fixed(buffer: &mut Vec<u8>, value: f64, decimals: u32) {
    let scale = pow10(decimals);
    let scaled = (value * exact_f64(scale)).round();

    if !scaled.is_finite() || scaled.abs() >= MAXIMUM_SCALED {
        buffer.push(b'?');
        return;
    }

    let magnitude = f64_to_u64(scaled.abs());
    if value.is_sign_negative() {
        buffer.push(b'-');
    }

    push_u64(buffer, magnitude / scale);
    if decimals == 0 {
        return;
    }

    buffer.push(b'.');
    let mut fraction = magnitude % scale;
    let mut divisor = scale / 10;
    for _ in 0..decimals {
        let step = divisor.max(1);
        buffer.push(digit_byte(fraction / step));
        fraction %= step;
        divisor /= 10;
    }
}

/// One decimal digit as its ASCII byte.
fn digit_byte(digit: u64) -> u8 {
    match u8::try_from(digit % 10) {
        Ok(digit) => b'0' + digit,
        Err(_) => b'0',
    }
}

/// Ten raised to `decimals`, saturating at the `u64` range.
const fn pow10(decimals: u32) -> u64 {
    let mut value = 1_u64;
    let mut remaining = decimals;
    while remaining > 0 {
        value = value.saturating_mul(10);
        remaining -= 1;
    }
    value
}

/// A scale factor as a float, exact for every scale this module uses.
fn exact_f64(scale: u64) -> f64 {
    match u32::try_from(scale) {
        Ok(narrow) => f64::from(narrow),
        Err(_) => MAXIMUM_SCALED,
    }
}

